-- Run only in an independent MySQL/MariaDB database. UTC connection. InnoDB required.
CREATE TABLE fp_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('ADMIN','VIEWER') NOT NULL DEFAULT 'VIEWER', active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_sessions (id_hash CHAR(64) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, csrf_hash CHAR(64) NOT NULL, expires_at DATETIME(3) NOT NULL, INDEX(expires_at), FOREIGN KEY(user_id) REFERENCES fp_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_competitions (id BIGINT UNSIGNED PRIMARY KEY, name VARCHAR(180) NOT NULL, country VARCHAR(100) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_teams (id BIGINT UNSIGNED PRIMARY KEY, name VARCHAR(180) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_fixtures (id BIGINT UNSIGNED PRIMARY KEY, competition_id BIGINT UNSIGNED NOT NULL, home_team_id BIGINT UNSIGNED NOT NULL, away_team_id BIGINT UNSIGNED NOT NULL, kickoff DATETIME(3) NOT NULL, status VARCHAR(12) NOT NULL, home_goals SMALLINT NULL, away_goals SMALLINT NULL, updated_at DATETIME(3) NOT NULL, INDEX(kickoff,status), FOREIGN KEY(competition_id) REFERENCES fp_competitions(id), FOREIGN KEY(home_team_id) REFERENCES fp_teams(id), FOREIGN KEY(away_team_id) REFERENCES fp_teams(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_bookmakers (id BIGINT UNSIGNED PRIMARY KEY, name VARCHAR(160) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_odds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, fixture_id BIGINT UNSIGNED NOT NULL, bookmaker_id BIGINT UNSIGNED NOT NULL, market VARCHAR(20) NOT NULL DEFAULT 'OVER_1_5', price DECIMAL(18,12) NOT NULL, price_text VARCHAR(32) NOT NULL, observed_at DATETIME(3) NOT NULL, source VARCHAR(32) NOT NULL DEFAULT 'API_FOOTBALL', payload_hash CHAR(64) NOT NULL, ingested_at DATETIME(3) NOT NULL, UNIQUE KEY uq_quote(fixture_id,bookmaker_id,market,observed_at,payload_hash), INDEX(fixture_id,observed_at), FOREIGN KEY(fixture_id) REFERENCES fp_fixtures(id), FOREIGN KEY(bookmaker_id) REFERENCES fp_bookmakers(id), CHECK(market='OVER_1_5'), CHECK(price>1)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_team_form (team_id BIGINT UNSIGNED NOT NULL, observed_at DATETIME(3) NOT NULL, history JSON NOT NULL, source VARCHAR(32) NOT NULL DEFAULT 'API_FOOTBALL', PRIMARY KEY(team_id), FOREIGN KEY(team_id) REFERENCES fp_teams(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_settings (id TINYINT PRIMARY KEY, min_confidence TINYINT NOT NULL DEFAULT 70, max_risk TINYINT NOT NULL DEFAULT 30, min_quality TINYINT NOT NULL DEFAULT 80, max_odds_age_seconds INT NOT NULL DEFAULT 900, max_selections TINYINT NOT NULL DEFAULT 8, restrict_teams BOOLEAN NOT NULL DEFAULT TRUE, max_per_competition TINYINT NOT NULL DEFAULT 2, updated_by BIGINT UNSIGNED NULL, updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CHECK(id=1), FOREIGN KEY(updated_by) REFERENCES fp_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO fp_settings(id) VALUES(1);
CREATE TABLE fp_model_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, version VARCHAR(64) NOT NULL UNIQUE, description TEXT NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO fp_model_versions(version,description) VALUES('empirical-form-2','Transparent last-five/last-ten/venue goals baseline with scoring-consistency risk; uncalibrated evidence confidence');
CREATE TABLE fp_generation (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, day DATE NOT NULL UNIQUE, admin_id BIGINT UNSIGNED NOT NULL, status ENUM('RUNNING','QUALIFIED','NO_QUALIFYING_TICKET','FAILED') NOT NULL, stage VARCHAR(80) NOT NULL, report JSON NOT NULL, started_at DATETIME(3) NOT NULL, finished_at DATETIME(3) NULL, FOREIGN KEY(admin_id) REFERENCES fp_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_predictions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, generation_id BIGINT UNSIGNED NOT NULL, fixture_id BIGINT UNSIGNED NOT NULL, odds_id BIGINT UNSIGNED NULL, probability DECIMAL(8,6) NULL, implied_probability DECIMAL(8,6) NULL, confidence DECIMAL(6,2) NULL, quality DECIMAL(6,2) NULL, risk DECIMAL(6,2) NULL, reason VARCHAR(100) NULL, explanation JSON NOT NULL, model_version BIGINT UNSIGNED NOT NULL, UNIQUE(generation_id,fixture_id), FOREIGN KEY(generation_id) REFERENCES fp_generation(id), FOREIGN KEY(fixture_id) REFERENCES fp_fixtures(id), FOREIGN KEY(odds_id) REFERENCES fp_odds(id), FOREIGN KEY(model_version) REFERENCES fp_model_versions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, generation_id BIGINT UNSIGNED NOT NULL UNIQUE, day DATE NOT NULL UNIQUE, created_by BIGINT UNSIGNED NOT NULL, published_by BIGINT UNSIGNED NULL, published_at DATETIME(3) NULL, original_odds VARCHAR(256) NOT NULL, settlement_odds VARCHAR(256) NULL, status ENUM('DRAFT','PUBLISHED','UNPUBLISHED') NOT NULL DEFAULT 'DRAFT', result ENUM('PENDING','WON','LOST','VOID') NOT NULL DEFAULT 'PENDING', created_at DATETIME(3) NOT NULL, FOREIGN KEY(generation_id) REFERENCES fp_generation(id), FOREIGN KEY(created_by) REFERENCES fp_users(id), FOREIGN KEY(published_by) REFERENCES fp_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_selections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ticket_id BIGINT UNSIGNED NOT NULL, fixture_id BIGINT UNSIGNED NOT NULL, prediction_id BIGINT UNSIGNED NOT NULL, bookmaker_id BIGINT UNSIGNED NOT NULL, market VARCHAR(20) NOT NULL DEFAULT 'OVER_1_5', price DECIMAL(18,12) NOT NULL, price_text VARCHAR(32) NOT NULL, observed_at DATETIME(3) NOT NULL, source VARCHAR(32) NOT NULL, payload_hash CHAR(64) NOT NULL, fixture_snapshot JSON NOT NULL, bookmaker_snapshot VARCHAR(160) NOT NULL, model_version VARCHAR(64) NOT NULL, probability DECIMAL(8,6) NOT NULL, confidence DECIMAL(6,2) NOT NULL, risk DECIMAL(6,2) NOT NULL, result ENUM('PENDING','WON','LOST','VOID','POSTPONED') NOT NULL DEFAULT 'PENDING', settled_at DATETIME(3) NULL, UNIQUE(ticket_id,fixture_id), FOREIGN KEY(ticket_id) REFERENCES fp_tickets(id), FOREIGN KEY(fixture_id) REFERENCES fp_fixtures(id), FOREIGN KEY(prediction_id) REFERENCES fp_predictions(id), FOREIGN KEY(bookmaker_id) REFERENCES fp_bookmakers(id), CHECK(market='OVER_1_5')) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_results (fixture_id BIGINT UNSIGNED PRIMARY KEY, status VARCHAR(12) NOT NULL, home_goals SMALLINT NULL, away_goals SMALLINT NULL, observed_at DATETIME(3) NOT NULL, payload_hash CHAR(64) NOT NULL, FOREIGN KEY(fixture_id) REFERENCES fp_fixtures(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_sync_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, job VARCHAR(32) NOT NULL, status ENUM('RUNNING','OK','FAILED') NOT NULL, started_at DATETIME(3) NOT NULL, finished_at DATETIME(3) NULL, count INT NOT NULL DEFAULT 0, error VARCHAR(255) NULL, INDEX(job,started_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NULL, action VARCHAR(64) NOT NULL, entity VARCHAR(64) NOT NULL, entity_id VARCHAR(64) NOT NULL, detail JSON NOT NULL, created_at DATETIME(3) NOT NULL, INDEX(created_at), FOREIGN KEY(actor_id) REFERENCES fp_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_system_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, severity VARCHAR(10) NOT NULL, message VARCHAR(255) NOT NULL, created_at DATETIME(3) NOT NULL, INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fp_provider_cache (cache_key VARCHAR(180) PRIMARY KEY, body JSON NOT NULL, expires_at DATETIME(3) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
